 */
public class StringUtils_join_TriageGen1Test {





    @Test
    public void testJoin_NoOfItemsZeroOrNegative() {
        Object[] array = {"A", "B", "C"};
        // endIndex - startIndex <= 0 should return EMPTY
        assertEquals("When noOfItems <= 0, return empty string", 
            "", StringUtils.join(array, ",", 2, 2));
        assertEquals("When noOfItems < 0, return empty string", 
            "", StringUtils.join(array, ",", 2, 1));
    }










