/**
 * Unit tests for org.apache.commons.lang3.StringUtils.join(Object[] array, String separator, int startIndex, int endIndex)
 */
public class StringUtils_join_TriageGen1Test {







    @Test
    public void testJoin_StandardUsage() {
        Object[] array = {"apple", "banana", "cherry"};
        assertEquals("Standard join with comma", 
            "apple,banana,cherry", StringUtils.join(array, ",", 0, 3));
        assertEquals("Join with subset", 
            "apple,banana", StringUtils.join(array, ",", 0, 2));
        assertEquals("Join single element", 
            "banana", StringUtils.join(array, ",", 1, 2));
    }








}

