/**
 * Unit tests for org.apache.commons.lang3.StringUtils.join(Object[] array, String separator, int startIndex, int endIndex)
 */
public class StringUtils_join_TriageGen1Test {









    @Test
    public void testJoin_WithNullElementsInArray() {
        Object[] array = {"A", null, "C"};
        // The code logic: if (array[i] != null) { buf.append(array[i]); }
        // This means null elements are skipped but the separator is still appended
        assertEquals("Null elements should be skipped but separator remains", 
            "A,,C", StringUtils.join(array, ",", 0, 3));

        Object[] arrayAllNull = {null, null};
        assertEquals("All null elements should result in empty string (after separators)", 
            "", StringUtils.join(arrayAllNull, ",", 0, 2));
    }






}

